#include "cquestdialog.hpp"
#include <algorithm>
namespace mxh::ui{void cQuestDialog::AddQuest(QuestEntry q){if(q.id==0||q.title.empty())return;if(std::none_of(m_quests.begin(),m_quests.end(),[&](const auto&x){return x.id==q.id;}))m_quests.push_back(std::move(q));}bool cQuestDialog::UpdateQuest(std::uint32_t id,QuestStatus s){for(auto& q:m_quests)if(q.id==id){q.status=s;return true;}return false;}bool cQuestDialog::Select(std::size_t i)noexcept{if(i>=m_quests.size())return false;m_selected=i;return true;}const QuestEntry* cQuestDialog::Selected()const noexcept{return m_selected<m_quests.size()?&m_quests[m_selected]:nullptr;}bool cQuestDialog::ClaimSelected(){auto*q=Selected();if(!q||q->status!=QuestStatus::Completed)return false;if(m_claim&&!m_claim(*q))return false;return UpdateQuest(q->id,QuestStatus::Claimed);}}
